/**
 * Handles focus events throughout the menu for proper menu use.
 *
 * - Adds a `focus` listener to every menu item so when it gains focus,
 *   it will set the item's containing menu's focus state
 *   to "self".
 *
 * @protected
 */
  _handleFocus() {
    this.elements.menuItems.forEach((menuItem, index) => {
      menuItem.dom.link.addEventListener("focus", () => {
        this.focusState = "self";
        this.currentChild = index;
      });
    });
    // Close the menu when focus leaves the menu
    this.dom.menu.addEventListener("focusout", (event) => {
      if (!this.dom.menu.contains(event.relatedTarget)) {
        const toggle = this.elements.controller ?? this.elements.parentMenu?.elements.controller;
        if (toggle) {
          toggle.close();
        }
      }
    });
  }
